export const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));
export function polylineLength(points){let n=0;for(let i=1;i<points.length;i++)n+=Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]);return n;}
function simplifyCenterline(points,tolerance){if(points.length<3||!tolerance)return points;const keep=new Set([0,points.length-1]),pending=[[0,points.length-1]],limit=tolerance*tolerance;while(pending.length){const [first,last]=pending.pop(),a=points[first],b=points[last],dx=b[0]-a[0],dy=b[1]-a[1],length=dx*dx+dy*dy;let max=limit,index=-1;for(let i=first+1;i<last;i++){const p=points[i],t=length?clamp(((p[0]-a[0])*dx+(p[1]-a[1])*dy)/length):0,d=(p[0]-a[0]-t*dx)**2+(p[1]-a[1]-t*dy)**2;if(d>max){max=d;index=i;}}if(index>=0){keep.add(index);pending.push([first,index],[index,last]);}}return [...keep].sort((a,b)=>a-b).map(i=>points[i]);}
export function makePath(points,smoothing=.5){points=simplifyCenterline(points,clamp(smoothing)*2);const f=clamp(smoothing)*.45,fmt=p=>p.map(v=>+v.toFixed(4)).join(' ');let d='M'+fmt(points[0]);for(let i=1;i<points.length-1;i++){const a=points[i-1],b=points[i],c=points[i+1];if(!f){d+='L'+fmt(b);continue;}d+='L'+fmt([b[0]+(a[0]-b[0])*f,b[1]+(a[1]-b[1])*f]);d+='Q'+fmt(b)+' '+fmt([b[0]+(c[0]-b[0])*f,b[1]+(c[1]-b[1])*f]);}return d+'L'+fmt(points.at(-1));}
// Each letter owns one time window, so none of its branches can drift past later letters.
export function makeSchedule(groups,chains,overlap=0){const byId=new Map(chains.map(c=>[c.id,c]));let cursor=0;const raw=[];for(const group of groups){const cs=group.strokes.map(id=>byId.get(id)).filter(Boolean);if(!cs.length)continue;const weights=cs.map(c=>Math.max(c.length,4));const duration=group.together?Math.max(...weights):weights.reduce((a,b)=>a+b,0);let within=0;cs.forEach((c,i)=>{raw.push({id:c.id,group:group.id,start:cursor+(group.together?0:within),duration:group.together?duration:weights[i],gStart:cursor,gEnd:cursor+duration});within+=weights[i];});cursor+=duration*(1-clamp(overlap,0,.9));}const end=Math.max(1,...raw.map(s=>s.start+s.duration));return raw.map(s=>({...s,start:s.start/end,duration:s.duration/end,end:(s.start+s.duration)/end,gStart:s.gStart/end,gEnd:s.gEnd/end}));}
export function eased(t,mode){t=clamp(t);if(mode!=='ease'||t===0||t===1)return t;let low=0,high=1;for(let i=0;i<22;i++){const u=(low+high)/2,x=3*(1-u)**2*u*.42+3*(1-u)*u*u*.58+u**3;if(x<t)low=u;else high=u;}const u=(low+high)/2;return 3*(1-u)*u*u+u**3;}
export function atProgress(progress,timing,mode){return eased((progress-timing.start)/timing.duration,mode);}
export function animationKeys(timing,draw,hold=0){const total=draw+hold,start=clamp(timing.start*draw/total),end=clamp(timing.end*draw/total);const times=[0],values=[1];if(start>0){times.push(start);values.push(1);}times.push(end);values.push(0);if(end<1){times.push(1);values.push(0);}return {times,values,total,start,end};}
export function moveItem(array,id,position){const index=array.findIndex(v=>(typeof v==='object'?v.id:v)===id);if(index<0)throw new Error('Item not found.');const next=[...array],item=next.splice(index,1)[0];next.splice(clamp(position,0,next.length),0,item);return next;}
export function nearbyOrder(chains){const rest=chains.map(c=>({...c,points:c.points.map(p=>[...p])})),out=[];if(!rest.length)return out;rest.sort((a,b)=>Math.min(a.points[0][1],a.points.at(-1)[1])-Math.min(b.points[0][1],b.points.at(-1)[1]));const first=rest.shift(),a=first.points[0],z=first.points.at(-1),dx=Math.abs(z[0]-a[0]),dy=Math.abs(z[1]-a[1]);if(dx>=dy*.5?a[0]>z[0]:a[1]>z[1])first.points.reverse();out.push(first);while(rest.length){const end=out.at(-1).points.at(-1);let best=0,reverse=false,min=Infinity;rest.forEach((c,i)=>{for(const rev of [false,true]){const p=rev?c.points.at(-1):c.points[0],d=Math.hypot(p[0]-end[0],p[1]-end[1]);if(d<min){min=d;best=i;reverse=rev;}}});const next=rest.splice(best,1)[0];if(reverse)next.points.reverse();out.push(next);}return out;}

// Brush fade: lagged, partly transparent copies of a stroke stack up to full opacity, giving the pen a soft leading edge.
export function brushLayers(softness,maxLag=.1,steps=6){const s=clamp(softness);if(!s)return [{lag:0,alpha:1}];return Array.from({length:steps+1},(_,j)=>({lag:s*maxLag*j/steps,alpha:1/(steps+1-j)}));}
export function lagTiming(timing,lag){const start=Math.min(timing.start+lag,1-1e-4),end=Math.min(timing.end+lag,1),gStart=Math.min((timing.gStart??timing.start)+lag,1-1e-4),gEnd=Math.min((timing.gEnd??timing.end)+lag,1);return {...timing,start,end,duration:end-start,gStart,gEnd};}

// One motion per letter: the easing curve spans the whole letter and each stroke takes its share of it, so the pen does not slow down and speed up between strokes.
export function strokeProgress(progress,timing,mode,continuous=true){if(!continuous||mode!=='ease'||timing.gStart===undefined||!(timing.gEnd>timing.gStart))return atProgress(progress,timing,mode);const span=timing.gEnd-timing.gStart,u=eased((progress-timing.gStart)/span,mode),a=(timing.start-timing.gStart)/span,b=(timing.end-timing.gStart)/span;return b>a?clamp((u-a)/(b-a)):u>=a?1:0;}
export function sampledKeys(timing,mode,draw,hold=0,steps=48){const total=draw+hold,g0=timing.gStart??timing.start,g1=timing.gEnd??timing.end,samples=[];for(let i=0;i<=steps;i++){const p=g0+(g1-g0)*i/steps;samples.push([p,1-strokeProgress(p,timing,mode,true)]);}
let first=0,last=samples.length-1;while(first<last&&samples[first+1][1]>=1)first++;while(last>first&&samples[last-1][1]<=0)last--;const kept=samples.slice(first,last+1),times=[],values=[];
if(clamp(kept[0][0]*draw/total)>0){times.push(0);values.push(1);}for(const [p,v] of kept){const t=clamp(p*draw/total);if(times.length&&t<=times.at(-1))continue;times.push(t);values.push(v);}if(times.at(-1)<1){times.push(1);values.push(kept.at(-1)[1]);}
const start=clamp(kept[0][0]*draw/total),end=clamp(kept.at(-1)[0]*draw/total);return {times,values,total,start,end};}
